<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,shallowRef} from 'vue'
import {request} from './api'
import {readRecovery,retryRecord,skipSequence,resumeContext,remapPreview,confirmRemap,type RecoveryRecord,type RecoveryBatch,type BatchItem,type ResumeUpload} from './recovery'
import type {FormalAssignment} from './formalUpload'
import QuickUploadView from './QuickUploadView.vue'
import FormalUploadView from './FormalUploadView.vue'
import SubmissionDetail from './SubmissionDetail.vue'
import type {ExamContext} from './navigation'
const props=defineProps<{context?:ExamContext;batchId?:string}>()
const emit=defineEmits<{changed:[]}>()
const records=shallowRef<RecoveryRecord[]>([]),batches=shallowRef<RecoveryBatch[]>([]),assignments=shallowRef<FormalAssignment[]>([]),busy=ref(false),uncertain=ref(false),error=ref(''),message=ref(''),consents=ref<Record<string,boolean>>({}),detailId=ref(''),resume=shallowRef<ResumeUpload>(),selected=shallowRef<RecoveryRecord>(),mapping=ref<Record<string,string>>({}),preview=shallowRef<Awaited<ReturnType<typeof remapPreview>>>(),remapConsent=ref(false)
let alive=true,revision=0
const fragments=computed(()=>(selected.value?.result.unmapped_answers||[]).filter((v):v is {answer_id:string;photo_index:number}=>!!v&&typeof v==='object'&&typeof (v as {answer_id?:unknown}).answer_id==='string'))
const choices=computed(()=>selected.value?.teacher_scoring_questions||[])
function resetRemap(){preview.value=undefined;remapConsent.value=false}
async function load(){const token=++revision;busy.value=true;error.value='';uncertain.value=false;consents.value={};resume.value=undefined;selected.value=undefined;resetRemap();try{const [r,a]=await Promise.all([readRecovery(),request<{assignments:FormalAssignment[]}>('/api/assignments')]);if(alive&&token===revision){records.value=r.submissions.filter(s=>(!props.batchId||s.batch_id===props.batchId)&&(!props.context?.assignmentId||s.assignment_id===props.context.assignmentId)&&(!props.context?.examId||s.exam_id===props.context.examId));batches.value=r.batches.filter(b=>(!props.batchId||b.batch_id===props.batchId)&&(!props.context?.assignmentId||b.assignment_id===props.context.assignmentId)&&(!props.context?.examId||b.exam_id===props.context.examId));assignments.value=a.assignments}}catch(e){if(alive&&token===revision)error.value=(e as Error).message}finally{if(alive&&token===revision)busy.value=false}}
async function mutate(action:()=>Promise<unknown>){if(busy.value||uncertain.value)return;const token=revision;busy.value=true;error.value='';message.value='';try{await action();if(!alive||token!==revision)return;emit('changed');await load();if(alive)message.value='操作已提交；状态以服务端刷新结果为准，成绩没有自动确认'}catch{if(alive&&token===revision){uncertain.value=true;error.value='操作结果未能确认。已停止写操作，不自动重试；请先刷新核实服务器状态。'}}finally{if(alive)busy.value=false}}
async function resumeItem(b:RecoveryBatch,item:BatchItem){if(busy.value||uncertain.value)return;busy.value=true;error.value='';try{resume.value=await resumeContext(b,item)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function mapped(){return fragments.value.map(f=>({answer_id:f.answer_id,sub_question_id:mapping.value[f.answer_id]||''}))}
async function getPreview(){if(!selected.value||busy.value)return;busy.value=true;resetRemap();try{const p=await remapPreview(selected.value.id,mapped());if(p.blocked||!p.images?.length||!p.preview_token||!p.preview_fingerprint)throw new Error('无法生成可验证的重新处理预览');preview.value=p}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function formal(b:RecoveryBatch){return !!assignments.value.find(a=>a.id===b.assignment_id)?.formal_layout_required||!!b.class_name}
function needsUpload(b:RecoveryBatch,item:BatchItem){return !item.submission_state&&item.sequence>=b.next_sequence&&['failed','reserved'].includes(item.upload_status)}
onMounted(load);onUnmounted(()=>{alive=false;revision++;records.value=[];batches.value=[];resume.value=undefined;preview.value=undefined})
</script>
<template><section><h3>异常恢复操作</h3><p>只有明确确认后才重试、原位重传或跳过。模型重试、题号重新处理，以及跳过后继续后续答卷都可能产生模型费用。没有自动重试。</p><button :disabled="busy" @click="load">刷新恢复状态</button><p v-if="busy" role="status">正在读取或提交…</p><p v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p>
 <article v-for="r in records" :key="r.id" class="point-record"><h4>待恢复答卷{{r.id}}</h4><p>{{r.assignment_name}} · {{r.state}} · {{r.result.mode}}</p><p v-if="r.result.mode==='rules-demo'">本份没有真实AI成绩。请先到系统管理配置模型；确认恢复会发起模型调用，可能产生费用。旧记录缺少双评标记时仅恢复主模型，不会自动增加另一模型。</p><p>{{r.retry_reason}}<span v-if="r.retry_wait_seconds">；等待{{r.retry_wait_seconds}}秒后刷新</span></p><button @click="detailId=r.id">查看恢复答卷详情</button><label class="check"><input type="checkbox" v-model="consents[r.id]" :disabled="busy||uncertain||!r.retryable">已核对服务商是否计费，明确确认本份人工重试</label><button :disabled="busy||uncertain||!r.retryable||!!r.retry_wait_seconds||!consents[r.id]" @click="mutate(()=>retryRecord(r,!!consents[r.id]))">确认重试此答卷</button> <button v-if="r.result.unmapped_answers?.length" :disabled="busy||uncertain" @click="selected=r;mapping={};resetRemap()">指定未匹配答案题号</button></article>
 <article v-for="b in batches" :key="b.batch_id" class="point-record"><h4>恢复批次{{b.batch_id}}</h4><p>{{b.status}} · 下一序号{{b.next_sequence}} / {{b.total_sequences}} · {{b.pause_reason}}</p><div v-for="item in b.items" :key="item.sequence"><p>第{{item.sequence}}份 · {{item.submission_id}} · {{item.submission_state||item.upload_status}}</p><button v-if="needsUpload(b,item)" :disabled="busy||uncertain" @click="resumeItem(b,item)">原位重传第{{item.sequence}}份照片</button><template v-if="b.status==='paused'&&b.pause_sequence===item.sequence"><label class="check"><input type="checkbox" v-model="consents[b.batch_id+':'+item.sequence]" :disabled="busy||uncertain">确认本份不计成绩、保留已有结果并继续后续序号</label><button :disabled="busy||uncertain||!consents[b.batch_id+':'+item.sequence]" @click="mutate(()=>skipSequence(b,item,!!consents[b.batch_id+':'+item.sequence]))">确认跳过第{{item.sequence}}份</button></template></div></article>
 <SubmissionDetail v-if="detailId" :id="detailId"/>
 <section v-if="selected"><h4>未匹配答案题号确认</h4><label v-for="f in fragments" :key="f.answer_id">答案片段{{f.answer_id}}（原第{{f.photo_index}}页）<a :href="'/api/submission-photo?submission_id='+selected.id+'&photo_index='+f.photo_index" target="_blank" rel="noopener">查看对应原图</a><select v-model="mapping[f.answer_id]" @change="resetRemap"><option value="">选择正确小题</option><option v-for="q in choices" :key="q.id" :value="q.id">{{q.label||q.id}} {{q.question}}</option></select></label><button :disabled="busy||uncertain||!fragments.length||fragments.some(f=>!mapping[f.answer_id])" @click="getPreview">预览题号重新处理的实际外发图</button><section v-if="preview"><figure v-for="(image,i) in preview.images" :key="i"><img :src="image.data_url" :alt="'题号重处理外发图'+(i+1)" class="upload-preview"></figure><details><summary>重处理提示词</summary><pre>{{preview.prompt}}</pre></details><label class="check"><input type="checkbox" v-model="remapConsent">已核对题号、完整外发图片和隐私，确认重新处理</label><button :disabled="busy||uncertain||!remapConsent" @click="mutate(()=>confirmRemap(selected!.id,mapped(),preview!,remapConsent))">确认题号并重新处理</button></section></section>
 <section v-if="resume"><button :disabled="busy" @click="resume=undefined">关闭原位重传</button><FormalUploadView v-if="formal(resume.batch)" :key="resume.item.submission_id" :resume="resume"/><QuickUploadView v-else :key="resume.item.submission_id" :resume="resume"/></section>
</section></template>
